import{_ as i,l as s,o as t,c as n,v as e,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"最小割的建模","description":"","frontmatter":{"title":"最小割的建模","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/min-cut-applications.md","filePath":"cs/min-cut-applications.md","lastUpdated":1789023840000}'),h={name:"cs/min-cut-applications.md"};function u(E,a,_,m,B,A){const r=s("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="最小割的建模" tabindex="-1">最小割的建模 <a class="header-anchor" href="#最小割的建模" aria-label="Permalink to &quot;最小割的建模&quot;">​</a></h1><div class="epigraph"><p>把「选或不选」写成 $s$ 侧与 $t$ 侧；项之间的代价写成跨边容量，最小割给出最优划分。</p><footer>—— 据 Ford and Fulkerson, 1956；项目选择见 Picard, Maximal Closure of a Graph, 1976；CLRS 第 26 章整理</footer></div><p>上一课<a href="/cs/min-cost-flow">最小费用最大流</a>给了带费用的流。许多组合划分其实<strong>不需要费用</strong>，只要 \\(s\\)–\\(t\\) 最小割。主干已证最大流 \\(=\\) 最小割。本课不重证。缺口是<strong>怎么建图</strong>：项目选择、图的闭包、二元势函数的子模特例。后课回到匹配的组合算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>顶点要分到 \\(S\\ni s\\) 或 \\(T\\ni t\\)。跨割边容量之和是代价。建模：想惩罚「\\(u\\) 在 \\(S\\)、\\(v\\) 在 \\(T\\)」就加边 \\(u\\to v\\) 容量 \\(=\\) 惩罚。想强制「\\(u\\) 在 \\(S\\) 则 \\(v\\) 在 \\(S\\)」则加无穷容量 \\(u\\to v\\)。项目选择：项目有利润（可负），有依赖「做 \\(A\\) 必须做 \\(B\\)」。把正利润连到 \\(t\\)、负利润从 \\(s\\) 连入，依赖无穷边，最小割对应最大闭包。</p><p>缺口是这些边的含义，不是 Dinic 实现。</p><h3 id="不是任意-0-1-规划" tabindex="-1">不是任意 0-1 规划 <a class="header-anchor" href="#不是任意-0-1-规划" aria-label="Permalink to &quot;不是任意 0-1 规划&quot;">​</a></h3><p>一般二次伪布尔优化 NP-hard。可表示成无向图割的，是子模（或正则）的那一类。无穷容量表示硬约束，数值太大要小心与真无穷的区别。不要把 TSP 的圈约束写成一张最小割就多项式——那会回到 NPC。</p><p><span class="marginnote">Picard 1976 最大闭包。图像二值分割的图割（Boykov 等）是同一语言，本课点名应用不进视觉课。后课 Hopcroft–Karp 是二分匹配的速度，不是割。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写清每个顶点属于 \\(s\\) 侧还是 \\(t\\) 侧的语义。列出硬约束（无穷边）与软代价（有限容量）。跑最大流，读残量 \\(s\\) 可达集。检查无穷边未被割。</p>',11)),(t(),l(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOD%5B%220-1%20%E5%88%92%E5%88%86%22%5D%20--%3E%20ST%5B%22s%20%E4%BE%A7%20%2F%20t%20%E4%BE%A7%22%5D%0A%20%20ST%20--%3E%20INF%5B%22%E6%97%A0%E7%A9%B7%E8%BE%B9%EF%BC%9A%E7%A1%AC%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20ST%20--%3E%20CAP%5B%22%E6%9C%89%E9%99%90%E8%BE%B9%EF%BC%9A%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20CAP%20--%3E%20CUT%5B%22%E6%9C%80%E5%B0%8F%E5%89%B2%20%3D%20%E6%9C%80%E4%BC%98%22%5D%0A%20%20INF%20--%3E%20CUT%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>多源多汇仍用超级源汇。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>割的容量把「跨界」的惩罚加起来；最大流最小割保证这是最小惩罚。依赖边无穷则最优割不会切开它，否则容量无穷。与费用流：若目标是运输量而非划分，用上一课；若目标是划分代价，用本课。</p><p>不要用最小生成树的割（切分定理那条最轻边）代替 \\(s\\)–\\(t\\) 容量割。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多重标签图割（α-expansion）全文。不把线性规划对偶展开——那是单纯形单元。后课默认：能写成 \\(s\\)–\\(t\\) 割的 0-1 划分可最大流求解。下一课二分图最大匹配的 \\(O(E\\sqrt V)\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>划分代价 = 跨边容量；硬约束用无穷。</li><li>项目选择 / 最大闭包是标准模板。</li><li>一般伪布尔优化不能都化成一张割。</li><li>出处：Ford and Fulkerson, 1956；Picard, 1976。</li></ul>',8))])}const C=i(h,[["render",u]]);export{T as __pageData,C as default};
